-- Venue Live Guest "Wedding Greenhouse". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara greenhouse), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'greenhouse', 'Wedding Greenhouse', 'greenhouse', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 164, 'center 38%',
  $t${"name":"Wedding Greenhouse","orn":"diamond","ui":{"ivory":"#FAFBF5","white":"#FFFFFF","soft":"#E9F0DF","soft2":"#C9DDB8","accent":"#6B8F5E","deep":"#3F5A3A","ink":"#34452F","mute":"#8A9A82","line":"#DCE8D0","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FDFEF9","ink":"#34452F","accent":"#6B8F5E","gold":"#D9A93F","leaf":"#E9F0DF","hbg":"rgba(250,251,245,.94)","hline":"#D9A93F","motif":"diamond"},"hud":{"bg":"rgba(63,90,58,.9)","acc":"#F2E3A0","on":"#3F5A3A"},"scr":{"wine":"#6B8F5E","veil":"250,251,245"}}$t$::jsonb
